int sign = (row + col) % 2 == 0 ? 1 : -1;
int r0 = 0, r1 = 0, c0 = 0, c1 = 0;
for (int i = 0; i < 3; ++i) {
    if (i == row) continue;
    for (int j = 0; j < 3; ++j) {
        if (j == col) continue;
        if (r0 == 0) {
            if (c0 == 0) c0 = j;
            else c1 = j;
        } else {
            if (c0 == 0) c0 = j;
            else c1 = j;
        }
        if (r0 == 0) r0 = i;
        else r1 = i;
    }
}
double a = m[r0][c0];
double b = m[r0][c1];
double c = m[r1][c0];
double d = m[r1][c1];
double minor_det = a*d - b*c;
return sign * minor_det;

